def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    background = max(set(v for row in grid for v in row),
                     key=lambda v: sum(row.count(v) for row in grid))
    seen = set()

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            r0, r1 = min(y for y, x in comp), max(y for y, x in comp)
            c0, c1 = min(x for y, x in comp), max(x for y, x in comp)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            perimeter = (all(grid[r0][x] == color for x in range(c0, c1+1)) and
                         all(grid[r1][x] == color for x in range(c0, c1+1)) and
                         all(grid[y][c0] == color for y in range(r0, r1+1)) and
                         all(grid[y][c1] == color for y in range(r0, r1+1)))
            if not perimeter:
                continue
            if any(grid[y][x] != background for y in range(r0+1, r1) for x in range(c0+1, c1)):
                continue
            fill = 7 if (r1-r0-1) % 2 else 2
            for y in range(r0+1, r1):
                for x in range(c0+1, c1):
                    out[y][x] = fill
    return out
